/**
 * Route name utilities for filtering auto-generated route names.
 *
 * Routes without an explicit `name` option get auto-generated names
 * prefixed with `$path_` (see path-helper.ts). These should not be
 * exposed in public APIs or type-level route maps.
 */

/**
 * Check if a route name is auto-generated (internal).
 * Routes without an explicit name option get names like "$path__health"
 * (at root) or "docs.$path__health" (under include()). The auto-generated
 * prefix is always "$path_" (see path-helper.ts). User-defined names
 * containing "$" (e.g. "docs.$admin") are valid and must be preserved.
 */
export function isAutoGeneratedRouteName(name: string): boolean {
  return name.split(".").some((segment) => segment.startsWith("$path_"));
}
